package org.fireflyframework.koinon.sdk.api;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import org.fireflyframework.koinon.sdk.*;
import org.fireflyframework.koinon.sdk.internal.Transport;
import org.fireflyframework.koinon.sdk.model.*;

public final class DocumentsApi {
private final Transport transport; private final String prefix;
public DocumentsApi(Transport transport,String tenantId){this.transport=Objects.requireNonNull(transport);this.prefix="/tenants/"+Transport.id(tenantId);}
public DocumentChunks chunks(String documentId,ChunkFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/documents/"+Transport.id(documentId)+"/chunks",null,options,transport.type(DocumentChunks.class));}
public DocumentChunks chunks(String documentId,ChunkFilter filter){return chunks(documentId,filter,RequestOptions.defaults());}
public DocumentChunks chunks(String documentId){return chunks(documentId,ChunkFilter.empty(),RequestOptions.defaults());}
public CompletableFuture<DocumentChunks> chunksAsync(String documentId,ChunkFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/chunks",null,options,transport.type(DocumentChunks.class));}
public CompletableFuture<DocumentChunks> chunksAsync(String documentId,ChunkFilter filter){return chunksAsync(documentId,filter,RequestOptions.defaults());}
public CompletableFuture<DocumentChunks> chunksAsync(String documentId){return chunksAsync(documentId,ChunkFilter.empty(),RequestOptions.defaults());}
public BinaryResponse original(String documentId,RequestOptions options){Objects.requireNonNull(options);return transport.binary("GET",prefix+"/documents/"+Transport.id(documentId)+"/original",options);}
public BinaryResponse original(String documentId){return original(documentId,RequestOptions.defaults());}
public CompletableFuture<BinaryResponse> originalAsync(String documentId,RequestOptions options){Objects.requireNonNull(options);return transport.binaryAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/original",options);}
public CompletableFuture<BinaryResponse> originalAsync(String documentId){return originalAsync(documentId,RequestOptions.defaults());}
public FileDownload downloadOriginal(String documentId,Path target,long maxBytes,RequestOptions options){Objects.requireNonNull(options);return transport.download("GET",prefix+"/documents/"+Transport.id(documentId)+"/original",target,maxBytes,options);}
public CompletableFuture<FileDownload> downloadOriginalAsync(String documentId,Path target,long maxBytes,RequestOptions options){Objects.requireNonNull(options);return transport.downloadAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/original",target,maxBytes,options);}
public ContentUpdate reingest(String documentId,DocumentReingestInput input,String expectedRevision,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);options=options.ifMatch(ApiSupport.precondition(expectedRevision));return transport.json("POST",prefix+"/documents/"+Transport.id(documentId)+"/reingest",input,options,transport.type(ContentUpdate.class));}
public ContentUpdate reingest(String documentId,DocumentReingestInput input,String expectedRevision){return reingest(documentId,input,expectedRevision,RequestOptions.defaults());}
public CompletableFuture<ContentUpdate> reingestAsync(String documentId,DocumentReingestInput input,String expectedRevision,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);options=options.ifMatch(ApiSupport.precondition(expectedRevision));return transport.jsonAsync("POST",prefix+"/documents/"+Transport.id(documentId)+"/reingest",input,options,transport.type(ContentUpdate.class));}
public CompletableFuture<ContentUpdate> reingestAsync(String documentId,DocumentReingestInput input,String expectedRevision){return reingestAsync(documentId,input,expectedRevision,RequestOptions.defaults());}
public ContentUpdate replace(String documentId,DocumentReplacement input,String expectedRevision,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);options=options.ifMatch(ApiSupport.precondition(expectedRevision));return transport.multipart("POST",prefix+"/documents/"+Transport.id(documentId)+"/content",input.file(),"file",input.mediaType(),ApiSupport.replacementFields(input),options,transport.type(ContentUpdate.class));}
public ContentUpdate replace(String documentId,DocumentReplacement input,String expectedRevision){return replace(documentId,input,expectedRevision,RequestOptions.defaults());}
public CompletableFuture<ContentUpdate> replaceAsync(String documentId,DocumentReplacement input,String expectedRevision,RequestOptions options){Objects.requireNonNull(options);Objects.requireNonNull(input);options=options.ifMatch(ApiSupport.precondition(expectedRevision));return transport.multipartAsync("POST",prefix+"/documents/"+Transport.id(documentId)+"/content",input.file(),"file",input.mediaType(),ApiSupport.replacementFields(input),options,transport.type(ContentUpdate.class));}
public CompletableFuture<ContentUpdate> replaceAsync(String documentId,DocumentReplacement input,String expectedRevision){return replaceAsync(documentId,input,expectedRevision,RequestOptions.defaults());}
public DocumentVersionPage versions(String documentId,DocumentHistoryFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions",null,options,transport.type(DocumentVersionPage.class));}
public DocumentVersionPage versions(String documentId,DocumentHistoryFilter filter){return versions(documentId,filter,RequestOptions.defaults());}
public DocumentVersionPage versions(String documentId){return versions(documentId,DocumentHistoryFilter.empty(),RequestOptions.defaults());}
public CompletableFuture<DocumentVersionPage> versionsAsync(String documentId,DocumentHistoryFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions",null,options,transport.type(DocumentVersionPage.class));}
public CompletableFuture<DocumentVersionPage> versionsAsync(String documentId,DocumentHistoryFilter filter){return versionsAsync(documentId,filter,RequestOptions.defaults());}
public CompletableFuture<DocumentVersionPage> versionsAsync(String documentId){return versionsAsync(documentId,DocumentHistoryFilter.empty(),RequestOptions.defaults());}
public DocumentVersion version(String documentId,String sourceVersionId,RequestOptions options){Objects.requireNonNull(options);return transport.json("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId),null,options,transport.type(DocumentVersion.class));}
public DocumentVersion version(String documentId,String sourceVersionId){return version(documentId,sourceVersionId,RequestOptions.defaults());}
public CompletableFuture<DocumentVersion> versionAsync(String documentId,String sourceVersionId,RequestOptions options){Objects.requireNonNull(options);return transport.jsonAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId),null,options,transport.type(DocumentVersion.class));}
public CompletableFuture<DocumentVersion> versionAsync(String documentId,String sourceVersionId){return versionAsync(documentId,sourceVersionId,RequestOptions.defaults());}
public DocumentExtractionPage extractions(String documentId,String sourceVersionId,DocumentHistoryFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/extractions",null,options,transport.type(DocumentExtractionPage.class));}
public DocumentExtractionPage extractions(String documentId,String sourceVersionId,DocumentHistoryFilter filter){return extractions(documentId,sourceVersionId,filter,RequestOptions.defaults());}
public DocumentExtractionPage extractions(String documentId,String sourceVersionId){return extractions(documentId,sourceVersionId,DocumentHistoryFilter.empty(),RequestOptions.defaults());}
public CompletableFuture<DocumentExtractionPage> extractionsAsync(String documentId,String sourceVersionId,DocumentHistoryFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/extractions",null,options,transport.type(DocumentExtractionPage.class));}
public CompletableFuture<DocumentExtractionPage> extractionsAsync(String documentId,String sourceVersionId,DocumentHistoryFilter filter){return extractionsAsync(documentId,sourceVersionId,filter,RequestOptions.defaults());}
public CompletableFuture<DocumentExtractionPage> extractionsAsync(String documentId,String sourceVersionId){return extractionsAsync(documentId,sourceVersionId,DocumentHistoryFilter.empty(),RequestOptions.defaults());}
public DocumentPartPage parts(String documentId,String sourceVersionId,String extractionId,DocumentPartFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.json("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/extractions/"+Transport.id(extractionId)+"/parts",null,options,transport.type(DocumentPartPage.class));}
public DocumentPartPage parts(String documentId,String sourceVersionId,String extractionId,DocumentPartFilter filter){return parts(documentId,sourceVersionId,extractionId,filter,RequestOptions.defaults());}
public DocumentPartPage parts(String documentId,String sourceVersionId,String extractionId){return parts(documentId,sourceVersionId,extractionId,DocumentPartFilter.empty(),RequestOptions.defaults());}
public CompletableFuture<DocumentPartPage> partsAsync(String documentId,String sourceVersionId,String extractionId,DocumentPartFilter filter,RequestOptions options){Objects.requireNonNull(options);options=Objects.requireNonNull(filter).applyTo(options);return transport.jsonAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/extractions/"+Transport.id(extractionId)+"/parts",null,options,transport.type(DocumentPartPage.class));}
public CompletableFuture<DocumentPartPage> partsAsync(String documentId,String sourceVersionId,String extractionId,DocumentPartFilter filter){return partsAsync(documentId,sourceVersionId,extractionId,filter,RequestOptions.defaults());}
public CompletableFuture<DocumentPartPage> partsAsync(String documentId,String sourceVersionId,String extractionId){return partsAsync(documentId,sourceVersionId,extractionId,DocumentPartFilter.empty(),RequestOptions.defaults());}
public DocumentPartContent part(String documentId,String sourceVersionId,String extractionId,String sourcePartId,RequestOptions options){Objects.requireNonNull(options);return transport.json("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/extractions/"+Transport.id(extractionId)+"/parts/"+Transport.id(sourcePartId),null,options,transport.type(DocumentPartContent.class));}
public DocumentPartContent part(String documentId,String sourceVersionId,String extractionId,String sourcePartId){return part(documentId,sourceVersionId,extractionId,sourcePartId,RequestOptions.defaults());}
public CompletableFuture<DocumentPartContent> partAsync(String documentId,String sourceVersionId,String extractionId,String sourcePartId,RequestOptions options){Objects.requireNonNull(options);return transport.jsonAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/extractions/"+Transport.id(extractionId)+"/parts/"+Transport.id(sourcePartId),null,options,transport.type(DocumentPartContent.class));}
public CompletableFuture<DocumentPartContent> partAsync(String documentId,String sourceVersionId,String extractionId,String sourcePartId){return partAsync(documentId,sourceVersionId,extractionId,sourcePartId,RequestOptions.defaults());}
public BinaryResponse versionOriginal(String documentId,String sourceVersionId,RequestOptions options){Objects.requireNonNull(options);return transport.binary("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/original",options);}
public BinaryResponse versionOriginal(String documentId,String sourceVersionId){return versionOriginal(documentId,sourceVersionId,RequestOptions.defaults());}
public CompletableFuture<BinaryResponse> versionOriginalAsync(String documentId,String sourceVersionId,RequestOptions options){Objects.requireNonNull(options);return transport.binaryAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/original",options);}
public CompletableFuture<BinaryResponse> versionOriginalAsync(String documentId,String sourceVersionId){return versionOriginalAsync(documentId,sourceVersionId,RequestOptions.defaults());}
public FileDownload downloadVersionOriginal(String documentId,String sourceVersionId,Path target,long maxBytes,RequestOptions options){Objects.requireNonNull(options);return transport.download("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/original",target,maxBytes,options);}
public CompletableFuture<FileDownload> downloadVersionOriginalAsync(String documentId,String sourceVersionId,Path target,long maxBytes,RequestOptions options){Objects.requireNonNull(options);return transport.downloadAsync("GET",prefix+"/documents/"+Transport.id(documentId)+"/versions/"+Transport.id(sourceVersionId)+"/original",target,maxBytes,options);}
}
